  "实验会如实显示失败，不能当作保证成功的技能。": "実験は失敗を正直に報告します。成功は保証されていません。",
  "已接入 · 实验": "統合・実験的",
  "MicroDock v1：仿真标签与触点代理。回桩已通过单轮检查；站姿离窝尚未通过当前试跑，可与坐姿版本对照。": "MicroDock v1 は、シミュレートされたタグと連絡先プロキシを使用します。 1 回のドッキング実行が成功しました。スタンディングアンドドッキングが経過していません。着席バージョンと比較してください。",
  "实验：采用源项目 74 cm 桌面与交错窄梯。策略实时推理，未播放轨迹；当前 CPU 试跑爬高后落地，未完成落台恢复。": "実験的: 上流の 74 cm デスクと交互の狭い踏み板。ライブ方策推論、軌跡の再生なし。現在の CPU トライアルは上昇した後、下降しました。デスクのリカバリに失敗しました。",
  "实验：12.5 cm 窄缝和 3 m 平台；使用三套策略及官方恢复。宽度与相对位置来自仿真定位，不是视觉。Mac 单轮通过，Linux 试跑未完成；不沿用作者成功率。": "実験: 12.5 cm のギャップと 3 m のプラットフォーム、3 つの方策と公式の回復。幅と相対位置は、視覚ではなくシミュレーションのローカリゼーションを使用します。 1 つの Mac CPU トライアルに合格しました。 Linux のロールアウトは完了していません。上流の成功率は適用されません。",
  "社区助跑滚翻策略，先走两秒、翻滚两秒，再恢复站立。采用源项目 PD 电机与电流限幅。": "コミュニティ助走ロール: 2 秒歩き、2 秒回転してから回復します。上流の PD モーターと電流制限を使用します。",
  "社区轮滑策略，已知路线的追踪控制器提供方向误差；八个实物标记均需正确绕过，碰撞或失稳不算成功。": "既知のパス コントローラーからのヘディング エラーのあるコミュニティ スケート 方策。 8 つの物理マーカーはすべて正しい側を通過する必要があります。衝突や落下は失敗します。",
  "实验：滑行时命令单脚承重，按接触力计时。当前单轮最长 0.36 秒，未达到 0.4 秒门槛；不保证长时间单脚滑。": "実験的: スケート中にシングルブレードのサポートを命令し、接触力によって測定します。現在の単一実行: 0.36 秒、0.4 秒のしきい値を下回っています。持続的な滑走は保証されません。",
  "八种高度，各用对应策略与模型。": "8 つの高さ。それぞれ方策とモデルが一致します。",
  "实时爬梯；当前试跑未完成桌面恢复。": "ライブはしご登り。デスクリカバリは完了していません。",
  "三阶段加官方恢复，CPU 单轮已通过。": "3 段階と公式回復。 1 回の CPU 実行が完了しました。",
  "完整碰撞与软垫；当前试跑未通过落地站稳。": "完全衝突モデルとソフトマット。安定した着陸が通過していません。",
  "站姿回桩通过，离窝尚未通过。": "スタンディングドックが通過しました。ドッキング解除は行われていません。",
  "八乘八距离视野": "8 × 8 奥行きビュー",
  "转头查看六十四束测距，颜色表示远近。": "頭を回転させて、距離ごとに色分けされた 64 の距離光線を探索します。",
  "六十四束 MuJoCo 射线，45° × 45° 视野，最远四米；无回波为灰色。这是理想仿真测距，没有模拟真实 ToF 噪声。": "64 MuJoCo 光線、45° × 45° の視野、4 メートルの制限。灰色は返品不可を意味します。実際の ToF ノイズのない理想的なシミュレートされた測距。",
