  "尝试后空翻": "バク転を試してみる",
  "高跷高度": "支柱の高さ",
  "实际转角": "実際の回転数",
  "实际腾空": "実際の放送時間",
  "官方 alpha_stand 策略；从明确设置的卧姿初态开始，双脚恢复站稳一秒才成功。": "公式 alpha_stand 方策;指定された横たわったポーズから始まります。両足は 1 秒間バランスを取り戻す必要があります。",
  "八档高度分别使用对应的策略、质量和碰撞模型；只能在仿真中尝试。更换高度会重新准备场景。20 cm 在 Linux 试跑中失稳，其他平台也可能失败。": "8 つの高さのそれぞれに、独自の方策、質量、衝突モデルがあります。シミュレーションのみ。高さを変えることで新たなシーンが生まれます。 20 cm Linux のロールアウトは失敗しました。他のプラットフォームでも失敗する可能性があります。",
  "实验：高台到软垫落差 0.8 m；软垫为数值接触模型。翻转完成后仍需落垫站稳，可能失败。": "実験: プラットフォームから数値ソフトコンタクトマットまで 0.8 m の落下。フリップを完了するには、やはり安定した着地が必要です。失敗する可能性があります。",
