  "不看球的位置，用身体感觉保持平衡。": "ボールの位置を見ずに、体の感覚を使ってバランスをとります。",
  "跳台长跳": "高床走り幅跳び",
  "跨过三十厘米间隙，落到较低的平台。": "30 cm の隙間を空けて、低いプラットフォームに着地します。",
  "快跑五秒": "5 秒間実行します",
  "球上平衡十秒": "ボール上で10秒バランス",
  "球上向前十秒": "ボール上を10秒前進",
  "跳到对面平台": "他のプラットフォームにジャンプします",
  "社区快跑策略：指令速度 2.2 m/s，实际速度与方向可能偏离；五秒后暂停，下次点击会自动准备起点。未做实体机验证。": "コミュニティランニング方策: 2.2 m/s コマンド。実際の速度と進行方向はずれることがあります。 5 秒後に一時停止します。次にクリックすると、自動的に開始の準備が整います。ハードウェア検証はありません。",
  "盲 LSTM 策略：输入只有本体感觉与记忆，不读取球的位置。在球上时可连续发指令；跌落后新指令会恢复仿真起点，不是自主爬球。": "ブラインド LSTM: 身体感知と記憶のみ、ボール状態入力なし。ボール上にいる間もコマンドは継続されます。落下後、新しいコマンドによりシミュレーションの開始が復元されます。これは自主登山ではありません。",
  "社区跳台策略：间隙 30 cm、落差 25 cm；已知几何参数，不使用视觉。双脚落台并稳定一秒才通过。": "コミュニティ プラットフォーム 方策: 30 cm のギャップ、25 cm のドロップ。ジオメトリは既知ですが、ビジョンはありません。両足が着地し、1 秒間安定していなければなりません。",
