  "需专用高跷模型、按高度匹配策略与接触验收。": "高床式の形状、高さに合わせた方策、接触チェックが必要です。",
  "需梯子场景与攀爬、落台、恢复策略切换。": "はしご、登り、着陸、回復方策の移行が必要です。",
  "需窄壁环境与进入、攀爬、退出策略串联。": "狭い壁と、入口、登り、出口の方策の順序が必要です。",
  "跨越 30 cm 间隙，双脚落台稳定一秒。": "30 cm の隙間を空けてください。両足で着地し、1秒間安定します。",
  "需完整碰撞模型与落地冲击、姿态验收。": "完全な衝突ジオメトリと着地の衝撃と姿勢のチェックが必要です。",
  "站姿后退回桩，与已接入的坐姿 v2 不同。": "統合された着座型 v2 とは異なる、直立逆ドッキング。",
  "坐姿回桩与离窝；虚拟电量，不是真实充电。": "着座ドッキングとドッキング解除。電気的な充電ではなく、仮想的な充電です。",
  "本房间已有场景，请切换或新建房间。": "この部屋ではシーンがアクティブです。シーンを切り替えたり、部屋を作成したりできます。",
