  "3 · 放下物品": "3 · 物体を置きます",
  "65,536 步": "65,536 歩",
  "CPU 训练实测": "CPU トレーニングの測定値",
  "DuckKing · 交互统计": "DuckKing · インタラクション統計",
  "DuckKing · 使用体验": "DuckKing · ユーザーエクスペリエンス",
  "DuckKing · 演示场景": "DuckKing · デモシーン",
  "DuckKing · 物理实验室": "DuckKing · 物理実験室",
  "DuckKing · 现场互动": "DuckKing · ライブインタラクション",
  "DuckKing · 训练新动作": "DuckKing · 新しいモーションをトレーニングする",
  "DuckKing · 语音平衡教练": "DuckKing · ボイスバランスコーチ",
  "DuckKing · 语音跷跷板教练": "DuckKing・音声シーソーコーチ",
