  "单鸭踢球": "シングルアヒルフットボール",
  "原人声版 · 对照": "オリジナルボーカルバージョン・比較",
  "参数": "パラメータ",
  "双鸭一起走": "一緒に歩きましょう",
  "双鸭互动": "2羽のアヒルのやりとり",
  "双鸭接触采样": "アヒルとアヒルの接触サンプル",
  "发布人 / 目标": "パブリッシャー/ターゲット",
