  "取消训练并保存": "トレーニングをキャンセルして保存",
  "变更提交": "変更点",
  "变更提交对比同一目标的上一次成功部署；待验收和失败记录不改变比较基准。每次最多显示 50 项，完整差异可通过 GitHub 链接查看。": "変更は、同じターゲットへの以前の成功したデプロイメントと比較されます。保留中のレコードや失敗したレコードによっても、そのベースラインは変更されません。最大 50 個のコミットが表示されます。完全な差分については、GitHub を参照してください。",
  "只听声音，也能分清谁在说话": "音声だけで話者を認識します",
  "只回中心站定": "中央に戻って長押しするだけ",
  "可说：“开始第二关，运行20秒”“用训练前的策略试试”“现在两边成绩怎么样”“停止圆盘”。": "試してください: 「レベル 2 を 20 秒間開始します」、「トレーニングされていない方策を試してください」、「双方の調子はどうですか?」、「ディスクを停止してください」。",
  "右侧任务控制器": "右側タスクコントローラー",
