  "右侧实时因果链": "右側に実際の因果関係の連鎖",
  "右侧指令、位置、板角与两侧配重轨迹随仿真时间变化": "シミュレーション時間にわたる右側のコマンド、位置、ボード角度、および両方の重量の軌道",
  "右侧控制器 · 等候指令": "右コントローラー · コマンドを待っています",
