  "启用合唱声音": "合唱団サウンドを有効にする",
  "和学会的策略比一比": "学習した方策に従って競争する",
  "和小鸭一起挑战": "アヒルと一緒にチャレンジ",
  "响应延迟": "応答遅延",
  "哪些是学来的，哪些是工程先验？": "何を学び、何が組み込まれますか?",
