  "未经过本项平衡任务训练。": "このバランス課題については訓練を受けていません。",
  "未训练": "未学習",
  "未训练官方基线": "未トレーニングの公式ベースライン",
  "本侧仿真时间": "こちら側のシミュレーション時間",
  "本地与灵矽：识别延迟": "ローカルと Linx: 認識遅延",
  "本地合成双声部，不使用云端 TTS。": "クラウド TTS を使用しない、ローカルで合成された 2 つの音声。",
  "本地命中率": "ローカル一致率",
  "本地持久缓存": "永続的なローカルキャッシュ",
  "本地排练当前关卡": "このレベルをローカルでリハーサルしてください",
  "本地编排 + 实时物理仿真；不使用麦克风。": "ローカル振付 + ライブ物理学;マイクはありません。",
  "本地识别 P50": "ローカル認識 P50",
  "本地识别与转交": "ローカル認識とハンドオフ",
  "本地：选中鸭一起翻跟头": "地元: 選ばれたアヒルが一緒に転がる",
  "本地：选中鸭齐舞": "地元: 選ばれたアヒルが一緒に踊ります",
  "本地：集结排队": "ローカル: 整列して集合",
  "本次值": "現在値",
  "本轮事件时间线": "このターンのタイムライン",
  "本轮最多 18 秒": "このラウンドは最大 18 秒",
  "本轮训练前的 PPO": "このトレーニング実行前の PPO",
  "本页最多保留最近 500 轮，并在启动时恢复私有轮转日志中的有效记录；轮转清理的旧记录不会伪造补齐。重启时未完成的轮次标为已中断。历史轮次仅恢复指标与动作，不回显识别文字；本次采集的识别文字经过已知凭据与常见设备标识脱敏，最多保留 2000 字符。原始录音不保存，脱敏事件另写入本地私有轮转日志。": "このページは最大 500 ターンを保持し、起動時に有効なプライベートローテーションログを復元します。削除された履歴は捏造されたものではありません。未完了のターンは再起動後に中断されます。復元された履歴には、トランスクリプトではなく、メトリクスとアクションが含まれます。新しくキャプチャされたテキストは、既知の認証情報と一般的なデバイス ID に合わせて編集され、2,000 文字に制限されます。生の録音は保存されません。編集されたイベントは、プライベートのローテーションされたログにも保存されます。",
  "板面和 280 g 配重均无电机，也没有按时间预设的运动轨迹。配重滑轨阻尼 1 N·s/m，板面阻尼 10 N·m·s/rad，均只阻碍运动，不会自动回中；板角限位约 ±6°。红色区只是标记，不吸附、不锁定配重。重力合力矩不等于脚部接触力矩。": "ボードにも 280 g のウェイトにもモーターやタイムスクリプト付きのパスはありません。レールの減衰は 1 N・s/m、ボードの減衰は 10 N・m・s/rad です。動きを中心に置くことなく抵抗します。基板の限界は約±6°です。赤いゾーンは単なるマーカーであり、磁気吸引やロックはありません。正味の重力トルクは足接触トルクではありません。",
  "板面响应来自：鸭脚接触力矩 + 配重经导轨传递的力矩 − 阻尼力矩 + 限位力矩": "ボード応答 = 足接触トルク + レールを通る重量トルク − ダンピングトルク + リミットトルク",
  "构建时间": "ビルド時間",
  "查看原始实测记录 ↗": "元の寸法を表示 ↗",
  "查看本次原始 JSON ↗": "この実行の生の JSON を表示する ↗",
