  "样本": "サンプル",
  "样本来源": "サンプルソース",
  "核对正在运行的版本，回看每次发布的结果。": "実行中のバージョンを確認し、各リリースの結果を確認します。",
  "桌上不掉拍 · 选曲直接开演": "ビートを逃すことはありません · 開始する曲を選択してください",
  "桌上合唱": "卓上合唱団",
  "桌上合唱 · 等待开演": "卓上合唱団 · 開始を待っています",
  "桌上合唱的歌曲音源": "卓上合唱団の音源",
  "桌边的星光 · 原创（非《夜空》）": "Starlight by the table · オリジナル (The Brightest Star ではありません)",
  "桌面浏览器": "デスクトップブラウザ",
  "概率比 ρ": "確率比 ρ",
  "模型 ©": "モデル©",
