  "轮次 / 时间": "ターン/時間",
  "轮滑": "ローラースケート",
  "轮滑下蹲": "スケート靴を履いてしゃがむ",
  "轮滑小鸭": "スケートアヒル",
  "轻戳 · 实际物理推力": "ナッジ・本物の物理的な力",
  "轻沙哑＋鼻音 · 推荐": "軽いラスプ + 鼻トーン · 推奨",
  "轻鼻音 · 清晰优先": "軽い鼻トーン・明瞭さ優先",
  "输入": "入力",
  "输入来自仿真真值，未使用摄像头视觉。任务 PPO 以 10 Hz 输出反馈力度，工程反馈函数将其转换为有界速度指令；冻结的官方步态以 50 Hz 输出 14 个关节的 PD 目标；MuJoCo 以 200 Hz 计算接触。": "入力では、カメラ ビジョンではなく、シミュレーションのグラウンド トゥルースを使用します。タスク PPO は 10 Hz でフィードバック強度を出力します。設計されたフィードバックは、それらを有界速度コマンドに変換します。凍結された公式歩行は、14 関節の PD 目標を 50 Hz で出力します。 MuJoCo は 200 Hz で接触を計算します。",
  "运行时长（秒）": "実行時間 (秒)",
  "返回工作台": "ワークベンチに戻る",
  "这一幕，发生了什么": "この行為で何が起こったのか",
  "这些指标能说明什么？": "これらの指標は何を示していますか?",
  "这次发生了什么": "今回の出来事",
  "这次，由你来改剧情。": "今度は話が変わります。",
  "进入跷跷板挑战": "シーソーチャレンジに参加してください",
  "进入转盘三关": "3 つのディスク レベルを入力してください",
  "进行中": "進行中",
  "连接与恢复": "接続と回復",
  "连接灵矽后，按住说话，松开执行；也可按住空格。": "Linx を接続し、押し続けると話し、放すと実行します。スペースバーも機能します。",
  "连接计数来自当前及可恢复的保留日志；重连耗时仅使用本次采集的单调时钟样本，最多保留500次。": "接続数には、現在保持されているログと回復可能なログが含まれます。再接続のタイミングには、このコレクションの単調クロック サンプルのみ (最大 500) が使用されます。",
  "选一个场景：先亲眼比较，再打开奖励函数和训练曲线。": "シーンを選択します。視覚的に比較し、その報酬関数とトレーニング曲線を調べます。",
