  "终点成功奖励": "最終成功報酬",
  "一次梯度更新使用多少条采样。": "1 回の勾配更新で使用されるサンプルの数。",
  "仅影响优化器使用的奖励尺度；验证回报与奖励分量曲线仍用原始单位。": "最適化に対する報酬のみを再スケールします。評価リターンとコンポーネント チャートは元の単位を維持します。",
  "价值预测误差在总损失中的权重。": "全損失における価値予測誤差の重み。",
  "同一批经验重复学习的轮数；不会增加环境步数。": "最適化は同じエクスペリエンスを引き継ぎます。環境ステップは追加されません。",
  "广义优势估计在短期预测与较长轨迹之间的折中。": "一般化された利点の推定は、短期的な予測と長期的な軌道をトレードします。",
  "每次优化更新参数的步长；本轮固定，曲线平坦是正常的。": "各パラメータ更新のステップサイズ。この実行では修正されているため、フラットなカーブは正常です。",
  "每轮收集的任务步数；总采样量还要乘并行环境数。": "ロールアウトごとに収集されるタスクステップ。合計に並列環境の数を掛けます。",
  "熵奖励的系数，鼓励尝试不同动作。": "さまざまなアクションを促すエントロピーボーナス係数。",
  "独立 CPU 采样进程数；梯度优化使用 1 个 Torch 线程。": "独立した CPU サンプリング プロセス。勾配の最適化では 1 つの Torch スレッドを使用します。",
  "相同观测与动作，新策略相对采样时策略的概率比。逐样本的概率比不在当前训练记录里；右侧教学滑块可计算一个假设样本。": "同じ観察とアクションについて、新しい方策の確率をサンプリング 方策の確率で割ったもの。サンプルごとの比率はこれらの記録には含まれていません。ティーチング スライダーは仮説サンプルを計算します。",
  "越接近 1，越重视稍后的奖励；不代表成功概率。": "1 に近いほど、後の報酬の重みが高くなります。それは成功確率ではありません。",
  "限制概率比在目标函数中的收益增长；不是硬性限制所有权重变化。": "すべての重みが直接変更されるわけではなく、目標内の確率比からのゲインを制限します。",
  "高斯动作分布的初始标准差；后续数值会学习变化，见优化曲线。": "初期ガウス作用分布偏差。最適化チャートに示されているように、学習中に変化します。",
  "d 是鸭子躯干在盘面坐标系里的离心距离，单位米。0.10 m 是奖励衰减尺度，不是成功半径；系数 2 提高靠近中心在总奖励中的比重。": "d は、円板座標における円板中心から胴体の距離 (メートル単位) です。 0.10 m は報酬減衰スケールであり、成功半径ではありません。係数2はセンタリングの重みを大きくします。",
  "场景已在另一页面切换": "別タブでシーンが変更されました",
  "回中站定规则": "センター復帰ルール",
  "仅配平板面规则": "理事会レベルのルールのみ",
  "4 × exp(−(距停靠中心 / 12 cm)²)。配重越靠近红色区中心，得分越高；奖励的是配重的位置，不是鸭子回中。": "4 × exp(−(ドッキング中心までの距離 / 12 cm)²)。重量が赤いターゲットに近づくとスコアが増加します。これはアヒルがセンターに戻るのではなく、ウェイトの位置に報酬を与えます。",
  "此音色未验证支持当前对话语言，请使用默认音色": "この音声は選択された言語で検証されていません。デフォルトの音声を使用します。",
