  "此历史记录使用第一版朝向奖励：朝向误差的余弦。第 1 关为 0。": "この履歴では、最初の船首方位報酬、つまり船首方位誤差のコサインが使用されます。レベル 1 の場合はゼロ。",
  "此历史记录只惩罚物理失败，不另惩罚终点未达标。": "この履歴は、追加のエンドポイント ペナルティなしで、物理的な障害のみにペナルティを与えます。",
