  "基线已经能过关，本关不能据此宣称 PPO 带来提升。": "ベースラインはすでに超えています。このレベルでは PPO の改善を実証できません。",
  "预定门槛：连续两次验证至少 18/20 成功。尚无数据。": "目標: 2 回連続の検証で少なくとも 18/20 の成功。まだデータがありません。",
  "一次运行一个 CPU 任务；关卡切换不会伪造或清除训练记录。": "一度に 1 つの CPU ジョブ。レベルを切り替えても、トレーニング記録は捏造も消去もされません。",
  "独立 CPU 训练任务已提交；网页曲线等候实际记录。": "独立した CPU トレーニングが提出されました。チャートは実際の測定を待ちます。",
