  "好动作的概率增大到一定程度后，继续增大不再增加这一项收益。": "適切なアクションの確率が十分に増加すると、それ以上増加してもこの目標項は向上しません。",
  "对坏动作同样取较小值；不是无论优势正负都把结果夹进同一个区间。": "不正なアクションの場合は、より小さい値も使用されます。クリッピングによって両方のアドバンテージ サインが同じ結果区間に強制されることはありません。",
