  "零速": "速度ゼロ",
  "右侧等待开始或已结束 · 以实际物理状态判定成绩。": "右側は待機中または終了しました · 結果は実際の物理学を使用します。",
  "直接说“向前走”，或点击前进／后退开始 PK。": "「前に歩いて」と言うか、前進/後退をクリックして決闘を開始します。",
  "左侧听你指挥，右侧自主行动。两侧同一初态、同一时钟，用相同停靠条件判定；语音识别期间仿真继续。方向不随视角改变。": "あなたは左をコントロールします。権利は自律的に行動します。どちらも初期状態、クロック、ドッキング基準を共有します。音声認識中もシミュレーションは続行されます。指示はカメラに従っていません。",
  "左侧单独练习，右侧保持站定；两侧物理同步推进，不计挑战成绩。方向不随视角改变。": "右を保持しながら左で練習します。両方の物理の世界は、得点することなく一緒に進みます。指示はカメラに従っていません。",
  "同一初态，不同脚步 → 不同板角 → 不同配重轨迹。规则对照时左侧只回中心站定。两侧均使用官方已训练步态，方向不随视角改变。": "同じ初期状態、異なるステップ→異なるボード角度→異なる重量経路。ルール比較では左のみセンターに戻ります。どちらも訓練された公式の歩き方を使用します。方向はカメラに依存しません。",
