  "方向键": "矢印キー",
  "这份训练记录属于其他物理任务，不能作为当前停靠成绩；可手动探索。": "このトレーニング レコードは別の物理タスクに属しているため、このドッキング タスクをスコア化できません。手動探索が可能です。",
  "自由配重停靠策略尚未完成评估；可选人工规则或手动探索。": "フリーウェイトドッキング政策は十分に評価されていません。手書きのルールまたは手動の探索を選択します。",
  "独立测试中": "独立したテスト",
  "训练完成": "トレーニングが完了しました",
  "环境未记录": "環境が記録されていません",
  "macOS 实测；跨平台回放可能不同": "macOS で測定。リプレイはプラットフォームによって異なる場合があります",
  "尚未达到连续两次验证 ≥18/20 的预设收敛门槛。曲线显示实际成绩，不把回报上涨当作成功。": "2 つの連続した検証で収束しきい値 ≥18/20 が満たされていません。グラフは実際の結果を示しています。リターンの上昇は成功ではありません。",
  "尚未选择可用 checkpoint。": "利用可能なチェックポイントが選択されていません。",
  "读取训练记录失败：": "トレーニング履歴の読み取りに失敗しました:",
  "等待真实采样。尚无数据时不绘制曲线。": "実物サンプルを待っています。データがなければ曲線は描画されません。",
  "竖线：Wilson 95% 区间": "縦棒: ウィルソン 95% 間隔",
  "u 是躯干竖直轴与世界竖直轴的点积；1 表示直立；前面的系数 1 是这一项的奖励权重。": "u は、トルソアップとワールドアップの内積です。 1は直立を意味します。先頭の 1 はこの報酬の重量です。",
  "ψ 是相对世界初始正前方的偏航角（rad）；0.35 rad 是奖励衰减尺度。第 2、3 关启用；第 1 关为 0；前面的系数 1 是朝向奖励权重。": "ψ は初期ワールドフォワード (rad) に対するヨーです。 0.35 rad は報酬の減衰を設定します。レベル 2 ～ 3 で有効、レベル 1 ではゼロ。先頭の 1 は見出し報酬に重みを付けます。",
  "每个任务控制步为 0.1 秒。靠近中心为正，远离为负；使用真实位置变化；系数 8 放大回中心速度的奖励。": "各タスクのステップは 0.1 秒続きます。実際の位置の変化を使用して、中心に向かう移動は正、遠方への移動は負です。ウェイト 8 は、内側への速度に対する報酬をスケールします。",
  "接触点处，脚的速度减去盘面的速度，取盘面切向长度，单位 m/s。圆盘运动不等于脚打滑；系数 0.15 决定滑速惩罚力度。": "接地時に、足の速度からディスクの速度を減算し、接線方向の大きさを m/s で計算します。ディスクの動きは足の滑りではありません。 0.15 ウェイトスリップペナルティ。",
  "a 是三个归一化任务动作。抑制突然变化，系数 0.025 是平滑权重，不是关节扭矩上限。": "a には、3 つの正規化されたタスク アクションが含まれています。重み 0.025 は突然の変化を防ぎます。ジョイントのトルク制限ではありません。",
  "I_failure 在物理失败，或正常挑战结束却未达到全部条件时为 1；手动停止不算正常挑战结果；10 为单次失败扣分。": "I_failure は、物理的な障害、または条件が満たされていない完了したチャレンジの場合は 1 です。手動停止は正常な結果ではありません。失敗するたびに 10 ポイントがかかります。",
  "只在完整挑战和减速结束、独立成功判定通过的最后一步给分；不按中途姿态推测成功；20 为完整成功的额外奖励。": "フルチャレンジ、減速、独立成功チェック後の最後のステップでのみ授与されます。中間のポーズは成功を意味するものではありません。完全に成功すると 20 が追加されます。",
